// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address claimer, uint256 amount, address otherAccount) public {
        // Bound amount to a reasonable value
        vm.assume(amount > 0 && amount < 1e30);
        // otherAccount shouldn't be zero
        vm.assume(otherAccount != address(0) && otherAccount != claimer);

        // Set up: transfer some shares to claimer via deposit and batch stake/deposit
        // Use vm.prank to fake calls from dnGmxJuniorVault and keeper

        // First, initialize the contract with arbitrary addresses
        // We need to set keeper to a non-zero address for the test
        vm.prank(address(0)); // owner is zero after deployment
        c.setKeeper(otherAccount);

        // try to call claim with the parameters
        vm.prank(claimer);
        (bool success, ) = address(c).call(abi.encodeWithSignature("claim(address,uint256)", address(0), amount));

        // After claiming, check that keeper is not zero address
        // The reference C keeps keeper unchanged, buggy M resets it
        assertTrue(c.keeper() != address(0), "Keeper should not be zero address");
    }
}

